func:
var data = msg.payload;

// Determine icon based on device_id or role
var icon = "fa-map-marker";
if(data.device_id && data.device_id.includes("hider")) {
    icon = "fa-eye-slash";
} else {
    icon = "fa-search";
}

msg.payload = {
    name: data.device_id,
    lat: data.latitude,
    lon: data.longitude,
    icon: icon,
    iconColor: data.gps_valid ? "green" : "red",
    extrainfo: "Battery: " + data.battery_v + "V<br>LoRa RSSI: " + data.lora_rssi + "<br>BLE RSSI: " + data.ble_rssi
};
return msg;

var p = msg.payload;
msg.topic = `INSERT INTO telemetry (device_id, timestamp, gps_valid, latitude, longitude, lora_rssi, ble_rssi, motion_detected, battery_v) \
VALUES ('${p.device_id}', datetime(${p.timestamp}, 'unixepoch'), ${p.gps_valid ? 1 : 0}, ${p.latitude}, ${p.longitude}, ${p.lora_rssi}, ${p.ble_rssi}, ${p.motion_detected ? 1 : 0}, ${p.battery_v})`;
return msg;

var p = msg.payload;
// Only executed if switch node passes (e.g. gps_valid is true)
msg.topic = `INSERT INTO stable_telemetry (device_id, timestamp, latitude, longitude, battery_v) \
VALUES ('${p.device_id}', datetime(${p.timestamp}, 'unixepoch'), ${p.latitude}, ${p.longitude}, ${p.battery_v}) \
ON CONFLICT(device_id) DO UPDATE SET \
timestamp=excluded.timestamp, \
latitude=excluded.latitude, \
longitude=excluded.longitude, \
battery_v=excluded.battery_v;`;
return msg;
